INSERT INTO public.plans (id, name, description, is_public, is_active, sort_order, metadata)
SELECT src.id, src.name, src.description, src.is_public, src.is_active, src.sort_order, src.metadata
FROM jsonb_to_recordset('[{"id":"business","name":"Business","description":"Multiunidade, equipe ampliada e módulos B2B","is_public":true,"is_active":true,"sort_order":30,"metadata":{}},{"id":"demo","name":"Demo","description":"Plano exclusivo para tenants de demonstração","is_public":false,"is_active":true,"sort_order":0,"metadata":{}},{"id":"pro","name":"Pro","description":"Módulos comerciais avançados e maior capacidade","is_public":true,"is_active":true,"sort_order":20,"metadata":{}},{"id":"starter","name":"Starter","description":"Base white-label com limites iniciais","is_public":true,"is_active":true,"sort_order":10,"metadata":{}}]'::jsonb) AS src(id text, name text, description text, is_public boolean, is_active boolean, sort_order integer, metadata jsonb)
ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, description=EXCLUDED.description, is_public=EXCLUDED.is_public, is_active=EXCLUDED.is_active, sort_order=EXCLUDED.sort_order, metadata=EXCLUDED.metadata;

