-- vertical_registry: 7 canonical global rows
INSERT INTO public.vertical_registry (id, name, description, is_enabled, default_theme, default_modules)
SELECT src.id, src.name, src.description, src.is_enabled, src.default_theme, src.default_modules
FROM jsonb_to_recordset('[{"id":"bakery","name":"Padaria","description":"Commerce, pedidos, delivery/pickup e encomendas","is_enabled":true,"default_theme":{"preset":"bakery-premium"},"default_modules":{"orders":true,"commerce":true}},{"id":"heavy-machinery","name":"Máquinas Pesadas","description":"Showroom B2B, inventory, leads, propostas, trade-in e suporte","is_enabled":true,"default_theme":{"preset":"industrial-premium"},"default_modules":{"crm":true,"quotes":true,"support":true,"inventory":true}},{"id":"led","name":"Painéis de LED / Comunicação Visual","description":"Catálogo B2B, configuração, vistoria, propostas, projetos e suporte","is_enabled":false,"default_theme":{},"default_modules":{"crm":true,"quotes":true,"projects":true}},{"id":"pet","name":"Pet Shop","description":"Tutores, pets, serviços, booking, commerce e loyalty","is_enabled":true,"default_theme":{"preset":"pet-premium"},"default_modules":{"pets":true,"booking":true,"commerce":true}},{"id":"religious-house","name":"Templo / Casa Religiosa","description":"CMS público, calendário, eventos, booking e módulos sensíveis opt-in","is_enabled":true,"default_theme":{"preset":"religious-house-premium"},"default_modules":{"events":true,"booking":true,"religiousSensitive":false}},{"id":"restaurant","name":"Restaurante","description":"Cardápio, reservas, pedidos e eventos","is_enabled":true,"default_theme":{"preset":"restaurant-premium"},"default_modules":{"events":true,"booking":true,"commerce":true}},{"id":"salon","name":"Salão / Beleza & Estética","description":"Serviços, profissionais, agenda, CRM, mídia e experiência white-label para beleza e estética","is_enabled":true,"default_theme":{"preset":"salon-premium"},"default_modules":{"crm":true,"media":true,"booking":true}}]'::jsonb) AS src(id text, name text, description text, is_enabled boolean, default_theme jsonb, default_modules jsonb)
ON CONFLICT (id) DO UPDATE SET name=EXCLUDED.name, description=EXCLUDED.description, is_enabled=EXCLUDED.is_enabled, default_theme=EXCLUDED.default_theme, default_modules=EXCLUDED.default_modules;

DO $qa_catalog_checks$
BEGIN
  IF (SELECT count(*) FROM public.roles) != 8 THEN RAISE EXCEPTION 'QA parity row count mismatch: roles'; END IF;
  IF (SELECT count(*) FROM public.permissions) != 42 THEN RAISE EXCEPTION 'QA parity row count mismatch: permissions'; END IF;
  IF (SELECT count(*) FROM public.role_permissions) != 159 THEN RAISE EXCEPTION 'QA parity row count mismatch: role_permissions'; END IF;
  IF (SELECT count(*) FROM public.plans) != 4 THEN RAISE EXCEPTION 'QA parity row count mismatch: plans'; END IF;
  IF (SELECT count(*) FROM public.features) != 24 THEN RAISE EXCEPTION 'QA parity row count mismatch: features'; END IF;
  IF (SELECT count(*) FROM public.plan_entitlements) != 96 THEN RAISE EXCEPTION 'QA parity row count mismatch: plan_entitlements'; END IF;
  IF (SELECT count(*) FROM public.vertical_registry) != 7 THEN RAISE EXCEPTION 'QA parity row count mismatch: vertical_registry'; END IF;
  IF EXISTS (SELECT 1 FROM public.roles WHERE tenant_id IS NOT NULL) THEN RAISE EXCEPTION 'QA contains unexpected tenant-scoped roles'; END IF;
  IF EXISTS (SELECT 1 FROM public.role_permissions rp LEFT JOIN public.roles r ON r.id=rp.role_id LEFT JOIN public.permissions p ON p.id=rp.permission_id WHERE r.id IS NULL OR p.id IS NULL) THEN RAISE EXCEPTION 'QA role/permission FK validation failed'; END IF;
  IF EXISTS (SELECT 1 FROM public.plan_entitlements pe LEFT JOIN public.plans p ON p.id=pe.plan_id LEFT JOIN public.features f ON f.key=pe.feature_key WHERE p.id IS NULL OR f.key IS NULL) THEN RAISE EXCEPTION 'QA entitlement FK validation failed'; END IF;
END;
$qa_catalog_checks$;
